	getAuthHandoffConfig(input: GetAuthHandoffConfigOperationInput): Promise<HandoffEntry | null> {
		const path = buildPath("/auth/handoff/config", [], [["integration_id", input.integrationId], ["completion", input.completion], ["redirect_uri", input.redirectUri], ["state", input.state], ["code_challenge", input.codeChallenge], ["code_challenge_method", input.codeChallengeMethod], ["instructions_id", input.instructionsId], ["screen_hint", input.screenHint]])
		return this.transport.request<HandoffEntry>(path, { method: "GET" })
	}

